  str_mail_vote_title_102 = "Apresiasi dari Batia",
  str_mail_vote_detail_1 = "Saya tidak pernah mengharapkan dukungan yang begitu kuat dari siapa pun... Terima kasih, Navigator. Saya akan mendukungmu dengan cara yang sama sebagai balasannya.",
  str_mail_vote_detail_2 = "Wow, Navigator, apakah kamu benar-benar berusaha keras hanya agar aku memiliki pakaian bagus untuk dikenakan? Oh, aku sangat terharu, aku akan memberikan beberapa Holy Water Shell untukmu sekarang juga!",
  str_mail_vote_detail_3 = "Apa gunanya pakaian baru...? Tapi jika itu dari kamu, aku memang menantikannya... Aku hanya ingin mengatakan... terima kasih.",
  str_mail_vote_detail_4 = "Astaga, semua usaha itu untuk pakaian baruku? Kamu tidak perlu repot-repot! Biarkan May angin sore membawa rasa terima kasihku padamu!",
  str_mail_vote_detail_5 = "Saat tumbuh besar, saya tidak pernah punya pakaian yang bisa kusebut milikku sendiri selain berbagai seragam. Terima kasih sudah membuatku memikirkan masalah ini, Navigator.",
  str_mail_vote_detail_6 = "Terima kasih atas ketekunanmu, Navigator. Kau membuatku menyadari mungkin saatnya untuk meningkatkan cara berpakaianku. Aku melihatnya sebagai bentuk disiplin dan aku akan berusaha untuk mempertahankannya.",
  str_mail_vote_detail_7 = "Sebagai seorang bangsawan, merupakan kehormatan bagiku untuk mendapatkan pengakuan dan dukungan dari Anda. Saya akui, saya tidak terlalu familiar dengan mode terbaru. Apakah tidak masalah untuk mendengar pendapat Anda suatu saat nanti?",
  str_mail_vote_detail_8 = "Terima kasih atas kepercayaan dan dukungan Anda. Apakah Anda sudah memberikan suara untuk Carleen? Dia telah bekerja keras dan saya harap Anda bisa menjaganya.",
  str_mail_vote_detail_9 = "Oh, Navigator hebat ♪ Sepertinya kamu sangat menyukai kami ♪ Namun begitu ♪ Tidak menghentikan garis rambutmu yang semakin surut ♪",
  str_mail_vote_detail_10 = "Terima kasih, Navigator, tapi bagaimana kamu tahu aku tidak punya uang untuk baju? Izinkan aku untuk membelikanmu secangkir kopi lain waktu, jika kamu tidak keberatan...",
  str_mail_vote_detail_11 = "Nah, kamu telah membantuku tanpa syarat sepanjang waktu, jadi saya tidak tahu bagaimana saya bisa membalas budi... Saya tahu, saya akan memainkan melodi khusus untukmu ketika tidak ada orang lain di sekitar! Apakah itu oke?",
  str_mail_vote_detail_12 = "Heh, menarik. Bagiku, aku selalu bisa menggunakan satu set pakaian bagus lagi. Terima kasih. Oh, aku akan memberimu sesuatu yang trendi juga sebagai balasan nanti saat aku sempat.",
  str_mail_vote_detail_13 = "Aku bisa merasakan kepercayaan darimu saat kamu memilihku. Apakah itu karena kasih sayang, pelaut pemberani?",
  str_mail_vote_detail_14 = "Ya, dukungan tepat waktu sangat penting seperti menyerang pada saat yang tepat, memerlukan pikiran yang cermat dan presisi yang kamu miliki, Navigator. Terima kasih, saya akan menghargai ini.",
  str_mail_vote_detail_15 = "Pfft, ini canggung. Berhenti berbasa-basi dan katakan apa yang kamu inginkan dariku... Wow, sungguh kejutan yang menyenangkan.",
  str_mail_vote_detail_16 = "Kamu berusaha keras untuk membuatku senang, bukan? Jadi, jenis pakaian apa yang kamu inginkan aku kenakan?",
  str_mail_vote_detail_17 = "Kamu ingin aku mendapatkan kesempatan ini? Terima kasih, Nak. Setelah aku menang, bagaimana kalau kita merayakannya dengan segelas atau dua minuman?",
  str_mail_vote_detail_18 = "Aku sudah terbiasa bersembunyi dalam bayang-bayang sejak lama, tapi aku masih mau bergaul dengan kalian anak muda sesekali. Aku hanya tidak menyangka akan mendapat dukungan sebanyak ini darimu. Baiklah, aku akan memberimu keunggulan tiga langkah di pertandingan catur kita berikutnya!",
  str_mail_vote_detail_19 = "Saya tidak bisa membayangkan kegembiraan dan antisipasi Anda, tetapi terima kasih meskipun begitu. Sebagai balasannya, apakah Anda mau tidur siang di peti kayu hitam?",
  str_mail_vote_detail_20 = "Wow, apakah ini benar-benar untukku? Meski kutukan menimpaku, aku masih beruntung kadang-kadang, seperti mendapatkan dukungan tak tergoyahkan dari kamu, Navigator. Izinkan aku merenung bagaimana cara mengucapkan terima kasih...",
  str_mail_vote_detail_21 = "Omong-omong, aku akan mengambilnya. Tapi, bukankah ini pemborosan uang untuk memberiku pakaian baru? Ubahlah agar cocok dengan Robyn jika aku menang, Boatscrapper.",
  str_mail_vote_detail_22 = "Kamu tidak perlu menghabiskan sumber daya untukku, Navigator. Pengeluaran seperti memelihara Colossus dan menampung tamu-tamu membutuhkan banyak uang. Namun, pikiran itu membuatku bahagia dan merasa diberkati!",
  str_mail_vote_detail_23 = "Terima kasih untuk ini! Pakaian yang awet dan pas yang memudahkan latihan adalah yang dibutuhkan oleh seorang prajurit. Ngomong-ngomong, kapan kamu akan berlatih bersamaku untuk sekali ini?",
  str_mail_vote_detail_24 = "Aha, kamu memang sahabat terbaikku! Lemari kostum apa pun selalu kurang satu \"potongan terakhir\" untuk sempurna. Kita benar-benar seirama! Terima kasih banyak!",
  str_mail_vote_detail_25 = "Aku tidak menyangka kamu peduli padaku sebanyak ini. Bagaimana kalau begini: Kamu bisa meminjam pakaian baru yang aku dapatkan, tapi kamu harus menjadi subjek tesku sebagai gantinya. Itu adil, kan?",
  str_mail_vote_detail_26 = "Saya beruntung dicintai oleh kamu. Hidup ini singkat, tetapi tidak sia-sia jika seseorang berhenti untuk mencium bunga mawar.",
  str_mail_vote_detail_27 = "Kulit yang sangat bagus ini pasti akan meningkatkan kinerja bermain game saya. Sepertinya kamu akhirnya mengerti, Navigator! Saya sangat menghargai itu!",
  str_mail_vote_detail_28 = "Terima kasih telah menunjukkan arah baru untukku. Aku tidak boleh kalah dari Reinhardt, setidaknya dalam hal pakaian yang dimiliki!",
  str_mail_vote_detail_29 = "Seragam baru? Apakah ini berarti arena baru? Tentu, teruslah memilih aku! Kamu akan mendapatkan keuntungan besar saat semuanya selesai!",
  str_mail_vote_detail_30 = "Sebenarnya, selama berpetualang bersamamu, Navigator, aku sudah mengumpulkan banyak pakaian indah, dan kamu masih menyimpan kesempatan berharga itu untukku? Baiklah, aku akan berusaha menjaga buku itu untukmu!",
  str_mail_vote_detail_31 = "Aku hanya akan memberitahumu ini, meong! Aku merasakan cintamu padaku dan itu membuatku sangat bahagia, meong! Setelah aku mencoba ini, ayo tidur siang di bawah sinar matahari, meong!",
  str_mail_vote_detail_32 = "Wow! Kau memang mengerti! Sesuatu yang cocok untuk dikenakan saat bertarung!—Benny\nAku juga mendapatkan satu? Keputusan bijak yang pantas aku hargai.—Curo",
  str_mail_vote_detail_33 = "Dukunganmu telah memberi saya banyak kekuatan, dan itu membuatmu sahabat yang layak dalam keadilan! Jika kamu tidak keberatan, izinkan saya untuk menjahit \"Keadilan\" pada pakaianmu!",
  str_mail_vote_detail_34 = "Apa? Ini pasti bukan bagian dari rencana, meskipun aku sama sekali tidak membencinya. Mari kita jadikan baju kustom sebagai bagian dari rencana. Aku akan bekerja keras untuk itu!",
  str_mail_vote_detail_35 = "Nah, bukan berarti aku kekurangan pakaian di sini, tapi karena kamu memilihku, yang bisa kulakukan adalah mencobanya... Tidak, jangan salah paham, aku sama sekali tidak menantikannya!",
  str_mail_vote_detail_36 = "Aku tahu pilihanmu, jadi izinkan aku untuk berterima kasih. Namun, meskipun berlian itu indah, yang benar-benar memikat adalah maknanya, benar bukan?",
  str_mail_vote_detail_37 = "Aku tidak menyangka kamu akan memilihku, Navigator. Kostum baru, ya? Ide itu membuatku bersemangat. Mungkin aku bisa menggunakannya untuk perjalanan survei berikutnya.",
  str_mail_vote_detail_38 = "Wow, aku suka acara seperti ini! Sudah lama sekali aku tidak membeli pakaian baru! Jika aku menang kostum baru, aku harus segera memamerkannya kepada Louise dan Yang Mulia Ratu!",
  str_mail_vote_detail_39 = "Sangat luar biasa mendapatkan begitu banyak suara dari kamu! Izinkan saya melakukan trik sihir untukmu sebagai tanda penghargaan! Elf, tolong siapkan kotak-kotak permen!",
  str_mail_vote_detail_40 = "Kostum baru? Aku rasa aku mengerti! Ini seperti memberikan cat baru pada alat dan mecha yang kupakai sesekali. Hehe, aku tidak sabar untuk melihat \"cat\" apa yang kamu punya untukku, Navigator.",
  str_mail_vote_detail_41 = "Yah, tidak bisa bilang aku tertarik dengan ini, tapi peluru, klip, dan selongsong semuanya berteriak ingin kulit baru, jadi izinkan aku berterima kasih atas nama mereka.",
  str_mail_vote_detail_42 = "Sungguh kejutan ini! Tahu tidak, kamu bisa saja bergabung dengan Rediesel Wrench jika kamu begitu menyukai saya! Lalu kamu tidak perlu memilih dan aku akan memberimu celana dari kakiku!",
  str_mail_vote_detail_43 = "Kamu memilihku? Aku sangat bahagia! Aku ingin memamerkan kostum baru yang kudapatkan kepada saudaraku dan kamu, Navigator.",
  str_mail_vote_detail_44 = "Apa, sebanyak itu suara? Bagaimana aku harus berterima kasih padamu? Kostum baru... Aku akan sangat senang jika itu Coolster dengan sarung tangan.",
  str_mail_vote_detail_45 = "Pakaian baru ini haruslah kostum cantik yang dirancang khusus untuk bintang utama... Saya tidak sabar untuk tampil di panggung! Melihat berapa kali kamu memilih saya, berikut ini tiket VIP untuk konsernya!",
  str_mail_vote_detail_46 = "Banyak cinta dari Rediesel dan si kekasih yang panas! Idola kamu Barbara juga telah ikut serta dalam kompetisi ini! Aku mendapatkan semangat dan dukunganmu! Nanti kamu akan mendapatkan foto yang sudah aku tanda tangani!",
  str_mail_vote_detail_47 = "Terima kasih sudah menyukai saya. Jika memungkinkan, saya ingin Eve juga mendapatkan kostum baru. Apakah kamu akan memilihnya juga?",
  str_mail_vote_detail_48 = "Tidak masalah apa yang dikenakan oleh teknisi, tapi aku tetap akan berterima kasih sebelumnya. Pria, bocor lagi...? Biarkan aku mengejarmu setelah aku memperbaikinya.",
  str_mail_vote_detail_49 = "Sudah lama aku menginginkan pakaian baru, tapi bagaimana kamu bisa tahu? Kamu menantikan aku mewawancaraimu dengan pakaian itu, bukan, Navigator?",
  str_mail_vote_detail_50 = "Ya, ya, semuanya berjalan sesuai harapan, tetapi tetap saja, dukungan Anda sangat dihargai. Semua bagian dari rencana The Knowledge, saya yakin.",
  str_mail_vote_detail_51 = "Oh, kamu memilih saya. Oke, saya akan menunggu hasilnya. Tapi jika saya melihat ada kecurangan, mereka harus bertanggung jawab pada duri saya.",
  str_mail_vote_detail_52 = "Navigator, meskipun kamu memilihku, aku masih... Tidak, setelah dipikir-pikir, apakah kamu mencoba menutupi kristal di tubuhku? Tak bisa kusangka aku gagal melihat niat mulia kamu...",
  str_mail_vote_detail_53 = "Sudahkah kamu memilih aku? Apakah kamu terpesona oleh pesonaku? Kenapa tidak datang dan minum bersamaku setelahnya? Tentu saja, kamu yang traktir.",
  str_mail_vote_detail_54 = "Mengorbankan segalanya untuk keyakinan yang besar itu sepadan; kedamaian batin, kewarasan, bahkan hidup dan jiwa kita... Terima kasih atas dukunganmu. Akan lebih baik lagi jika kamu bergabung dengan kami.",
  str_mail_vote_detail_55 = "Jadi, aku harus masuk karena kamu memilihku? Tidak mungkin, aku hanya ingin menang jika kamu tidak memilihku! Mengerti? Suaramu membuatku sedikit bahagia, tapi hanya sedikit, jadi jangan berpikir terlalu banyak tentang itu!",
  str_mail_vote_detail_56 = "Tolong jangan tempatkan aku bersama siapa pun dalam kompetisi. Aku suka ruang dan ketenangan... Tunggu, aku tidak menyuruhmu pergi. Juga, terima kasih atas dukunganmu...",
  str_mail_vote_detail_57 = "Whoa, saya tidak pernah menyangka kamu akan mendukung saya. Apakah selera musikmu sudah meningkat? Kalau begitu, izinkan saya memainkan sebuah lagu untukmu sebagai ungkapan terima kasih yang tulus!",
  str_mail_vote_detail_58 = "Saya menghargai dukungan Anda yang memberi saya gelar ini. Terima kasih. Saya telah menolak kehormatan sebelumnya karena saya menerima kebahagiaan waktu yang lama. Tapi untuk Anda dan pencarian ke masa lalu dengan orang tertentu itu, saya akan terus bekerja keras.",
  str_mail_vote_detail_59 = "Pembakaran akan mengubah semua keindahan menjadi abu, jadi apa yang kamu harapkan? Ide kamu membingungkan... tapi aku akan memenuhi harapanmu sebagai penghargaanku karena kamu memilihku.",
  str_mail_vote_detail_60 = "Kamu ingin aku memiliki kesempatan mendapatkan pakaian baru? Sebagai gantinya, aku bisa menceritakan sebuah kisah dahulu kala... Benar, ini tidak ada hubungannya dengan bintang-bintang tetapi pakaian baru sang Kaisar.",
  str_mail_vote_detail_61 = "Apa kamu punya masalah dengan seragam tipisku? Apapun. Tak peduli apa yang aku kenakan, itu tidak akan mengurangi pesona dan kehebatanku, tapi kamu tetap pantas mendapat pujian karena memilih orang yang tepat.",
  str_mail_vote_detail_62 = "Terima kasih atas sikap baiknya. Karena segalanya ada dalam kehendak alam, apakah Anda tertarik untuk berjalan-jalan di hutan bersama saya untuk menikmati keindahan alam?",
  str_mail_vote_detail_63 = "Kamu tampak sangat tertarik untuk mengubah penampilanku. Sejak suaramu, sebuah simbol yang disebut kebahagiaan telah ditambahkan ke dalam ingatanku. Rasanya... luar biasa.",
  str_mail_vote_detail_64 = "Apakah fakta bahwa kamu memilihku sebanyak itu berarti kamu sangat menyukaiku? Jika Mia mengetahuinya, dia mungkin akan menangis bahagia!",
  str_mail_vote_detail_65 = "Apakah ini ide Dayna? Bukan? Saya pikir... Jadi ini bagaimana kamu sangat menghargai saya? Saya akan berusaha sebaik mungkin untuk tidak mengecewakanmu...",
  str_mail_vote_detail_66 = "Aku terkejut. Pasti ada ratusan Aurorian di Colossus, namun kamu memberikan suaramu yang berharga untukku. Aku akan membalas dukunganmu tiga kali lipat.",
  str_mail_vote_detail_67 = "Saya lega melihat kamu baik-baik saja karena kamu meluangkan waktu untuk peduli tentang apa yang dikenakan seorang veteran. Saya menerima tawaran dan jaga dirimu baik-baik.",
  str_mail_vote_detail_68 = "Apakah aku akan menjadi cantik? Terima kasih. Aku tidak menyangka ini dan aku sangat bahagia.",
  str_mail_vote_detail_69 = "Biasanya, hakim memiliki kode berpakaian mereka sendiri. Namun, karena kamu percaya ada kebutuhan, saya akan menerimanya dengan senang hati. Saya sangat menghargai ini, dan sampai kita bertemu lagi.",
  str_mail_vote_detail_70 = "Hai teman, bahkan tentara bayaran tahu tentang kamu memilih saya. Saya tersentuh kamu tidak melupakan saya. Menang atau kalah, saya bersedia tampak lebih baik untuk kamu.",
  str_mail_vote_detail_71 = "Terima kasih, teman. Aku telah melihat banyak penawaran di Umbraton dan aku tidak merasakannya. Kamu ingin aku menang kali ini...? Yah, bagaimana kalau meminta guild untuk ikut serta?",
  str_mail_vote_detail_72 = "Saya telah mengukir pikiran dan salam Anda di es Istana Musim Dingin. Saya senang melihat Anda tetap begitu murni meskipun segala yang telah Anda lalui. Terima kasih.",
  str_mail_vote_detail_73 = "Saya melihat kamu memilih saya. Saya jujur tidak mengharapkan untuk berlenggak-lenggok di atas panggung sebagai penyelenggara... Terima kasih, tetapi saya lebih peduli apakah kamu menikmati pesta tersebut.",
  str_mail_vote_detail_74 = "Wow, apa kejutan yang hebat! Saya selalu ingin menjadi bagian dari acara seperti ini, berdandan dan menikmati sorotan! Janjikan kamu akan berada di panggung bersamaku!",
  str_mail_vote_detail_75 = "Apakah Anda terlibat dalam semacam konspirasi, Kapten, atau apakah Anda ditakdirkan untuk mendukung seorang Ascended seperti saya? Anda tidak perlu memberi tahu saya! Sangat penting untuk mendapatkan dukungan dalam pertarungan melawan yang tidak diketahui. Terima kasih!",
  str_mail_vote_detail_76 = "Kamu ingin melihatku dalam pakaian selain seragam ini? Aku bisa menuruti, jika itu permintaanmu. Sebagai tanda terima kasihku, aku akan mentraktirmu putaran berikutnya. Jangan khawatir, aku akan memesan sesuatu yang normal.",
  str_mail_vote_detail_77 = "Malam Putih tinggi-tinggi! Apakah ini untukku? Ya, saya melihat saya harus berusaha memenuhi harapan Anda. Terima kasih, Caelestite terakhir. Jangan lupa untuk memberi nutrisi pada dirimu dan minum lebih banyak air.",
  str_mail_vote_detail_78 = "Hei, Caelestite kecil, apakah ini suara untukku? Hmm... Ruby sepertinya tidak ada di sini, jadi aku pasti benar. Terima kasih! Tapi dengan kamu memanjakan aku, aku harus menang sekarang, bukan?!",
  str_mail_vote_detail_79 = "Bukankah itu Navigator! Sudah lama aku tidak memiliki pakaian bagus. Tidak peduli hasilnya, aku sangat menghargai pikiranmu!",
  str_mail_vote_detail_80 = "Kapan Navigator yang pemalu ini menjadi begitu berani? Jadi kamu ingin melihatku dalam pakaian tertentu, ya? Jangan khawatir, aku akan memenangkannya untukmu.",
  str_mail_vote_detail_81 = "Aku sudah punya cukup pakaian, anak! Dan aku terus merusak seragam... Tapi terima kasih, anak. Untuk membalasnya, aku akan membuat agenda pelatihan baru khusus untuk kamu.",
  str_mail_vote_detail_82 = "Grand Marshal adalah panutan Illumina, dan kamu ingin aku berubah menjadi sesuatu yang lain? Aku membuatnya sulit bagimu? Tidak apa-apa, aku tidak bisa meragukan niat baik seorang kawan, jadi terima kasih! Aku akan menang dalam kontes ini.",
  str_mail_vote_detail_83 = "Ingin Axelia terlihat lebih cantik? Tapi aku sudah bercahaya. Bagaimana kesan yang akan aku tinggalkan dengan kostum yang berbeda, ya? Hmm, aku tidak yakin, tapi aku tahu aku harus berterima kasih padamu.",
  str_mail_vote_detail_84 = "Oh, terima kasih atas dukungannya! Baju baru akan mengurangi berapa kali aku kembali ke Colossus dengan seragam yang penuh noda darah! Maaf, semoga aku tidak membuatmu jijik ketika itu terjadi.",
  str_mail_vote_detail_85 = "Terima kasih telah membantuku. Aku akan memilihmu jika kontes seperti ini terjadi lagi. Jadi, bagaimana pendapatmu tentang kompetisi untuk ikat pinggang yang paling kokoh dan ketat?",
  str_mail_vote_detail_86 = "Saya melihat Anda memiliki waktu luang untuk menyaksikan saya dalam pakaian baru... Saya menghargainya. Dan jika diberi kesempatan, saya akan terlihat dalam semua kemegahan saya!",
  str_mail_vote_detail_87 = "Kamu ingin memanfaatkan kesempatan ini untuk membuat pakaian baru untukku? Saya sangat berterima kasih dan akan menghargainya. Namun... apakah mungkin untuk membuat kostum kucing untuk saudara saya?",
  str_mail_vote_detail_88 = "Kamu ingin memesan pakaian baru untukku? Itu sangat baik dari kamu. Meskipun saya memiliki lemari pakaian yang indah, itu menjadi pudar di hadapan kejujuran manismu.",
  str_mail_vote_detail_89 = "Kamu benar-benar ingin memberiku beberapa benang bagus? Sangat dihargai. Dan kamu tahu itu tidak akan adil jika aku tidak melakukan sesuatu yang baik untukmu sebagai balasannya, bukan?",
  str_mail_vote_detail_90 = "Untukku? Apakah kamu yakin? Terima kasih banyak! Aku tidak tahu harus berkata apa selain itu. Aku akan melakukan yang terbaik, jadi tolong terus bantu aku.",
  str_mail_vote_detail_91 = "Pakaian hanyalah penutup, namun kamu berhasil memberikan makna khusus pada mereka. Terima kasih, Caelestite muda. Saya menghargai kejujuran dalam memberikan hadiah kepada seorang kurir.",
  str_mail_vote_detail_92 = "Hoamm... Oh, aku merasa tidak enak bangun dan melihatmu berlarian untukku. Aku harus membalas budi. Aku harus mencatatnya... di jurnal ku... hoamm...",
  str_mail_vote_detail_93 = "Saya berterima kasih atas suara Anda! Saya hanya bergabung untuk memastikan keadilan kompetisi dan hasilnya tidak begitu berarti bagi saya, tetapi masih merupakan suatu kehormatan mendapatkan pengakuan dari Anda.",
  str_mail_vote_detail_94 = "Kamu ingin melihatku dalam kostum petani, bukan? Aku akan memberi tahu bahwa keluargaku berada dalam bisnis mewah! Aku akan menerima suaramu jika kamu memaksa, tapi bagaimana bisa satu suara cukup?!",
  str_mail_vote_detail_95 = "Terima kasih atas dukunganmu, meski sejujurnya saya tidak yakin bisa menang dalam acara yang begitu meriah. Namun, jika kamu tertarik, kita bisa bertemu di luar panggung. Saya memiliki banyak fakta menarik untuk dibagikan.",
  str_mail_vote_detail_96 = "Terima kasih. Saya tidak mengharapkan kamu peduli apakah saya memiliki cukup kostum untuk infiltrasi. Meskipun saya tidak memenangkan pakaian baru yang cocok untuk misi, saya akan memastikan saya dapat menyesuaikan tugas berikutnya dari kamu.",
  str_mail_vote_detail_97 = "Aku merasa bersalah atas semua dukungan yang kamu berikan padaku. Aku berjanji memberimu magang dan hidangan gourmet yang dibuat oleh gadget, hanya untuk kamu memberiku pakaian tanpa aku memenuhi apa pun. Aku malu. Aku akan mengeja namaku terbalik jika aku tidak menepati janjiku di lain waktu!",
  str_mail_vote_detail_98 = "Wow, terima kasih sudah memilih untuk membuatkan saya pakaian baru! Suara, suara, saya mendapatkan suara! Mungkin tidak mendapatkan pakaian baru, tapi saya tidak peduli! Seorang teman sejati lebih baik daripada pakaian apa pun!",
  str_mail_vote_detail_99 = "Kamu ingin mendapatkan kostum baru untukku? Ini memalukan... Aku tidak merasa pantas mendapatkannya karena aku berlarian di gunung sepanjang hari. Tapi aku bisa memberimu beberapa gelang yang bagus, meskipun begitu.",
  str_mail_vote_detail_100 = "Terima kasih, Navigator. Kamu masih memikirkan saya bahkan dalam kontes seperti ini, membantu saya menang. Sebenarnya, saya tidak terlalu peduli dengan penampilan, tetapi saya akan mengingat ini.",
  str_mail_vote_detail_101 = "Bonus dari The Last Caelestite? Hadiah untuk Zeta sang Prajurit? Wow, betapa indahnya, Last Caelestite! Tunggu saja, Zeta tak terkalahkan!",
  str_mail_vote_detail_102 = "Terima kasih... Dari semua perspektif, penampilan memang berfungsi untuk menutupi bagian-bagian berkinerja tinggi yang tidak menarik. Tapi daripada menghabiskan uang untuk itu, lebih baik jika itu gratis!",
  str_mail_vote_detail_103 = "Dalam perjalanan yang panjang ini, saya sering mengingat teman-teman yang berjuang di samping saya; keberanian dan kekuatan mereka telah memberi saya banyak dorongan. Saya telah melihat banyak musuh jatuh di bawah pedang saya dan merasa sakit dan lelah yang dibawa pertempuran. Tapi setiap kali saya mengayunkan pedang, itu adalah komitmen yang kokoh terhadap keyakinan saya. Saya percaya bahwa pedang tidak hanyalah senjata, tetapi juga simbol dari semangat, semangat yang tidak putus-putus."
}
